/**
 * Fills the LOCAL EMULATORS with fake schools, areas, parents and children.
 *
 *   firebase emulators:start --project demo-school-carpool   (terminal 1)
 *   npm --prefix functions run seed:emulator                 (terminal 2)
 *
 * PRIVACY: only fake data. The script refuses to run unless it is pointed at
 * the emulators and at a `demo-` project, so it can never touch a real one.
 * Running it twice gives the same result (fixed ids, upserts).
 *
 * Parent IDs here are generated by the seed only. In the app, only a Cloud
 * Function creates them (Prompt 2).
 */
import { initializeApp } from "firebase-admin/app";
import { getAuth } from "firebase-admin/auth";
import { GeoPoint, Timestamp, getFirestore } from "firebase-admin/firestore";

const projectId = process.env.GCLOUD_PROJECT ?? process.env.GCLOUD_PROJECT_ID ?? "";

function refuse(reason: string): never {
  console.error(`seed: refusing to run: ${reason}`);
  process.exit(1);
}

if (!process.env.FIRESTORE_EMULATOR_HOST) refuse("FIRESTORE_EMULATOR_HOST is not set");
if (!process.env.FIREBASE_AUTH_EMULATOR_HOST) refuse("FIREBASE_AUTH_EMULATOR_HOST is not set");
if (!projectId.startsWith("demo-")) refuse(`project "${projectId}" is not a demo- project`);

initializeApp({ projectId });
const db = getFirestore();
const auth = getAuth();

// --- Fake data ---------------------------------------------------------------

/** Letters and digits that cannot be confused: no 0, O, 1 or I. */
const PARENT_ID_ALPHABET = "23456789ABCDEFGHJKLMNPQRSTUVWXYZ";

/** Small deterministic PRNG so every run produces the same data. */
function prng(seed: number): () => number {
  let s = seed >>> 0;
  return () => {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 0x100000000;
  };
}
const rand = prng(20261113);

function parentId(): string {
  let id = "";
  for (let i = 0; i < 8; i++) id += PARENT_ID_ALPHABET[Math.floor(rand() * PARENT_ID_ALPHABET.length)];
  return id;
}

interface SeedSchool {
  id: string;
  nameAr: string;
  nameEn: string;
  governorate: string;
  city: string;
  lat: number;
  lng: number;
  areas: Array<{ id: string; nameAr: string; nameEn: string; lat: number; lng: number }>;
}

// Invented schools with made-up positions in Cairo and Giza.
const schools: SeedSchool[] = [
  {
    id: "school-nile-intl", nameAr: "مدرسة النيل الدولية (تجريبية)", nameEn: "Nile International School (test)",
    governorate: "Cairo", city: "Maadi", lat: 29.9602, lng: 31.2569,
    areas: [
      { id: "area-maadi-degla", nameAr: "دجلة", nameEn: "Degla", lat: 29.9590, lng: 31.2700 },
      { id: "area-maadi-sarayat", nameAr: "السرايات", nameEn: "Sarayat", lat: 29.9650, lng: 31.2500 },
    ],
  },
  {
    id: "school-pyramids-lang", nameAr: "مدرسة الأهرام للغات (تجريبية)", nameEn: "Pyramids Language School (test)",
    governorate: "Giza", city: "6th of October", lat: 29.9727, lng: 30.9430,
    areas: [
      { id: "area-october-h1", nameAr: "الحي الأول", nameEn: "District 1", lat: 29.9700, lng: 30.9500 },
      { id: "area-october-zayed", nameAr: "الشيخ زايد", nameEn: "Sheikh Zayed", lat: 30.0200, lng: 30.9800 },
    ],
  },
  {
    id: "school-heliopolis-kg", nameAr: "حضانة مصر الجديدة (تجريبية)", nameEn: "Heliopolis Kindergarten (test)",
    governorate: "Cairo", city: "Heliopolis", lat: 30.0911, lng: 31.3220,
    areas: [
      { id: "area-helio-korba", nameAr: "الكوربة", nameEn: "Korba", lat: 30.0900, lng: 31.3200 },
      { id: "area-helio-nozha", nameAr: "النزهة", nameEn: "Nozha", lat: 30.1100, lng: 31.3400 },
    ],
  },
  {
    id: "school-newcairo-amer", nameAr: "مدرسة القاهرة الجديدة الأمريكية (تجريبية)", nameEn: "New Cairo American School (test)",
    governorate: "Cairo", city: "New Cairo", lat: 30.0300, lng: 31.4700,
    areas: [
      { id: "area-newcairo-rehab", nameAr: "الرحاب", nameEn: "Rehab", lat: 30.0600, lng: 31.4900 },
      { id: "area-newcairo-5th", nameAr: "التجمع الخامس", nameEn: "Fifth Settlement", lat: 30.0100, lng: 31.4300 },
    ],
  },
];

const firstNames = ["Sara", "Omar", "Mona", "Karim", "Laila", "Youssef", "Nour", "Hany"];
const firstNamesAr = ["سارة", "عمر", "منى", "كريم", "ليلى", "يوسف", "نور", "هاني"];
const childNames = ["Adam", "Malak", "Ziad", "Farida", "Ali", "Jana", "Hamza", "Salma", "Yassin", "Habiba"];
const statuses = ["verified", "verified", "verified", "pending", "unverified", "verified", "rejected", "verified"];

/** Rounds to about 500 m, like the server will for real homes (Prompt 5). */
function roundCoord(value: number): number {
  return Math.round(value * 200) / 200;
}

async function upsertAuthUser(uid: string, email: string, phoneNumber: string, displayName: string, verified: boolean) {
  try {
    await auth.updateUser(uid, { email, phoneNumber, displayName });
  } catch {
    await auth.createUser({ uid, email, phoneNumber, displayName });
  }
  await auth.setCustomUserClaims(uid, verified ? { verified: true } : null);
}

async function main(): Promise<void> {
  const now = Timestamp.now();
  const batch = db.batch();

  for (const s of schools) {
    batch.set(db.collection("schools").doc(s.id), {
      nameAr: s.nameAr,
      nameEn: s.nameEn,
      governorate: s.governorate,
      city: s.city,
      location: new GeoPoint(s.lat, s.lng),
      source: "seed",
      status: "active",
      createdAt: now,
    });
    for (const a of s.areas) {
      batch.set(db.collection("areas").doc(a.id), {
        schoolId: s.id,
        nameAr: a.nameAr,
        nameEn: a.nameEn,
        center: new GeoPoint(a.lat, a.lng),
        createdAt: now,
      });
    }
  }

  let childCount = 0;
  for (let i = 0; i < firstNames.length; i++) {
    const uid = `seed-parent-${i + 1}`;
    const school = schools[i % schools.length];
    const area = school.areas[i % school.areas.length];
    const status = statuses[i];
    // Fake numbers in a clearly artificial range; emulator only.
    const phone = `+2010000000${String(i + 1).padStart(2, "0")}`;
    const email = `parent${i + 1}@example.com`;

    await upsertAuthUser(uid, email, phone, firstNames[i], status === "verified");

    batch.set(db.collection("users").doc(uid), {
      parentId: parentId(),
      firstName: firstNames[i],
      firstNameAr: firstNamesAr[i],
      lastName: "Test",
      phone,
      email,
      status,
      language: i % 3 === 0 ? "en" : "ar",
      createdAt: now,
    });

    batch.set(db.collection("parentLocations").doc(uid), {
      approxLocation: new GeoPoint(roundCoord(area.lat + (rand() - 0.5) * 0.01), roundCoord(area.lng + (rand() - 0.5) * 0.01)),
      areaId: area.id,
      schoolId: school.id,
      radiusKm: 3,
      showOnMap: i !== 4,
      notifyNewParents: true,
    });

    const kids = 1 + (i % 2);
    for (let k = 0; k < kids; k++) {
      const childId = `seed-child-${i + 1}-${k + 1}`;
      batch.set(db.collection("children").doc(childId), {
        parentId: uid,
        firstName: childNames[childCount % childNames.length],
        age: 5 + ((i + k) % 9),
        grade: `G${1 + ((i + k) % 8)}`,
        schoolId: school.id,
        schoolIdChecked: status === "verified",
        createdAt: now,
      });
      childCount++;
    }
  }

  await batch.commit();
  console.log(
    `seed: ${schools.length} schools, ${schools.length * 2} areas, ${firstNames.length} parents, ${childCount} children in ${projectId}`,
  );
}

main().catch((error: unknown) => {
  console.error("seed failed:", error instanceof Error ? error.message : error);
  process.exit(1);
});
